  function localize(key, lang = 'en', params = {}) {
    const l = (lang === 'de') ? 'de' : ((lang === 'id') ? 'id' : 'en');
    const parts = key.split('.');
    let cur = TRANSLATIONS[l];
    for (const p of parts) {
      if (cur && cur[p] !== undefined) cur = cur[p];
      else { cur = null; break; }
    }
    if (cur === null || cur === undefined) {
      let fallback = TRANSLATIONS.en;
      for (const fp of parts) {
        if (fallback && fallback[fp] !== undefined) fallback = fallback[fp];
        else { fallback = key; break; }
      }
      cur = fallback;
    }
    if (typeof cur === 'string' && params && typeof params === 'object') {
      for (const [paramKey, paramVal] of Object.entries(params)) {
        cur = cur.replace(new RegExp(`\\{${paramKey}\\}`, 'g'), paramVal);
      }
    }
    return cur;
  }

  // --- DEFAULT CELESTIAL ASSETS (Built-in with Alpha Transparency) ---
  const DEFAULT_MOON_TEXTURE = 'data:image/webp;base64,';
  const DEFAULT_SUN_TEXTURE = 'data:image/webp;base64,';
  const DEFAULT_EARTH_TEXTURE = 'data:image/webp;base64,';

  // --- LUNAR ASTRONOMICAL CALCULATOR ---
  const SYNODIC_MONTH = 29.53058867;
  const KNOWN_NEW_MOON = new Date('2024-01-11T11:57:00Z').getTime();

  function calculateMoonPhase(date = new Date()) {
    const diffDays = (date.getTime() - KNOWN_NEW_MOON) / (1000 * 60 * 60 * 24);
    const cycles = diffDays / SYNODIC_MONTH;
    const phaseFraction = cycles - Math.floor(cycles); // 0.0 to 1.0
    const ageDays = phaseFraction * SYNODIC_MONTH;
    const illumination = Math.round((1 - Math.cos(phaseFraction * 2 * Math.PI)) / 2 * 100);

    let phaseKey = 'new_moon';
    let phaseNameEn = 'New Moon';
    let phaseNameDe = 'Neumond';

    if (phaseFraction < 0.03 || phaseFraction > 0.97) {
      phaseKey = 'new_moon';
      phaseNameEn = 'New Moon';
      phaseNameDe = 'Neumond';
    } else if (phaseFraction < 0.22) {
      phaseKey = 'waxing_crescent';
      phaseNameEn = 'Waxing Crescent';
      phaseNameDe = 'Zunehmende Sichel';
    } else if (phaseFraction < 0.28) {
      phaseKey = 'first_quarter';
      phaseNameEn = 'First Quarter';
      phaseNameDe = 'Erstes Viertel';
    } else if (phaseFraction < 0.47) {
      phaseKey = 'waxing_gibbous';
      phaseNameEn = 'Waxing Gibbous';
      phaseNameDe = 'Zunehmender Mond';
    } else if (phaseFraction < 0.53) {
      phaseKey = 'full_moon';
      phaseNameEn = 'Full Moon';
      phaseNameDe = 'Vollmond';
    } else if (phaseFraction < 0.72) {
      phaseKey = 'waning_gibbous';
      phaseNameEn = 'Waning Gibbous';
      phaseNameDe = 'Abnehmender Mond';
    } else if (phaseFraction < 0.78) {
      phaseKey = 'last_quarter';
      phaseNameEn = 'Last Quarter';
      phaseNameDe = 'Letztes Viertel';
    } else {
      phaseKey = 'waning_crescent';
      phaseNameEn = 'Waning Crescent';
      phaseNameDe = 'Abnehmende Sichel';
    }

    // Days until next full moon (phaseFraction = 0.5)
    let daysToFull = (0.5 - phaseFraction);
    if (daysToFull < 0) daysToFull += 1.0;
    daysToFull = Math.round(daysToFull * SYNODIC_MONTH);

    // Days until next new moon (phaseFraction = 1.0)
    let daysToNew = (1.0 - phaseFraction);
    daysToNew = Math.round(daysToNew * SYNODIC_MONTH);

    return {
      phaseFraction,
      ageDays: Math.round(ageDays * 10) / 10,
      illumination,
      phaseKey,
      phaseNameEn,
      phaseNameDe,
      daysToFull,
      daysToNew
    };
  }

  
  // --- ASTRONOMICAL CONSTANTS & COORDINATE CALCULATOR ---
  const TO_RAD = Math.PI / 180;
  const TO_DEG = 180 / Math.PI;

  function calculateLocalSiderealTime(date = new Date(), lonDeg = 0) {
    const jd = (date.getTime() / 86400000) + 2440587.5;
    const d = jd - 2451545.0; // days since J2000.0
    let gmst = 18.697374558 + 24.06570982441908 * d;
    gmst = ((gmst % 24) + 24) % 24;
    let lstHours = gmst + (lonDeg / 15.0);
    lstHours = ((lstHours % 24) + 24) % 24;
    return lstHours * 15.0; // degrees [0, 360)
  }

  function equatorialToHorizontal(raDeg, decDeg, lstDeg, latDeg) {
    const phi = latDeg * TO_RAD;
    const dec = decDeg * TO_RAD;
    let ha = (lstDeg - raDeg) * TO_RAD;
    const sinAlt = Math.sin(phi) * Math.sin(dec) + Math.cos(phi) * Math.cos(dec) * Math.cos(ha);
    const alt = Math.asin(Math.max(-1, Math.min(1, sinAlt))) * TO_DEG;
    const cosAz = (Math.sin(dec) - Math.sin(phi) * Math.sin(alt * TO_RAD)) / (Math.cos(phi * TO_RAD) * Math.max(0.001, Math.cos(alt * TO_RAD)));
    let az = Math.acos(Math.max(-1, Math.min(1, cosAz))) * TO_DEG;
    if (Math.sin(ha) > 0) az = 360 - az;
    return { alt, az, visible: alt > 0 };
  }

  function calculateMoonPosition(date = new Date(), latDeg = 50, lonDeg = 10) {
    const jd = (date.getTime() / 86400000) + 2440587.5;
    const d = jd - 2451545.0; // days since J2000.0

    const L = ((218.316 + 13.176396 * d) % 360) * TO_RAD;
    const M = ((134.963 + 13.064993 * d) % 360) * TO_RAD;
    const F = ((93.272 + 13.229350 * d) % 360) * TO_RAD;

    const lMoon = L + (6.289 * Math.sin(M)) * TO_RAD;
    const bMoon = (5.128 * Math.sin(F)) * TO_RAD;
    const eps = (23.439 - 0.0000004 * d) * TO_RAD;

    const sinDec = Math.sin(bMoon) * Math.cos(eps) + Math.cos(bMoon) * Math.sin(eps) * Math.sin(lMoon);
    const dec = Math.asin(Math.max(-1, Math.min(1, sinDec))) * TO_DEG;

    const y = Math.cos(bMoon) * Math.cos(eps) * Math.sin(lMoon) - Math.sin(bMoon) * Math.sin(eps);
    const x = Math.cos(bMoon) * Math.cos(lMoon);
    let ra = ((Math.atan2(y, x) * TO_DEG) % 360 + 360) % 360;

    const lstDeg = calculateLocalSiderealTime(date, lonDeg);
    return equatorialToHorizontal(ra, dec, lstDeg, latDeg);
  }

